// storeInterfaceOverlay presents a fake that holds a storage.Store in its Store field
// as that store's whole method set. Build it with storeOverlay.
type storeInterfaceOverlay struct {
	fake  any
	field reflect.Value
}

// storeInterfaceOverlays keeps one overlay per comparable fake, so the server's store
// identity checks see one store for one fake, as they did when it embedded
// the store.
var storeInterfaceOverlays sync.Map

// storeOverlay wraps fake, a struct (or a pointer to one, so later assignments
// show) whose Store field, its own or an embedded struct's, holds the
// storage.Store its methods do not override.
func storeOverlay(fake any) *storeInterfaceOverlay {
	value := reflect.ValueOf(fake)
	memoize := value.Comparable()
	if memoize {
		if existing, ok := storeInterfaceOverlays.Load(fake); ok {
			return existing.(*storeInterfaceOverlay)
		}
	}
	if value.Kind() == reflect.Pointer {
		value = value.Elem()
	}
	field := value.FieldByName("Store")
	if !field.IsValid() || field.Type() != reflect.TypeFor[storage.Store]() {
		panic("storeOverlay: fake has no Store field of type storage.Store")
	}
	overlay := &storeInterfaceOverlay{fake: fake, field: field}
	if memoize {
		actual, _ := storeInterfaceOverlays.LoadOrStore(fake, overlay)
		return actual.(*storeInterfaceOverlay)
	}
	return overlay
}

func (o *storeInterfaceOverlay) base() storage.Store {
	base, _ := o.field.Interface().(storage.Store)
	return base
}

